{"command": "python3 - <<'PY'
import csv, math
rows=list(csv.reader(open('/data/reader/PL1.csv')))
data={r[0]:float(r[1]) for r in rows[1:]}
# standards cols 1,2
std_conc={'A':0,'B':25,'C':50,'D':100,'E':150,'F':200,'G':300,'H':400}
X=[];Y=[]
for col in [1,2]:
    for row,c in std_conc.items():
        X.append(c);Y.append(data[f'{row}{col}'])
print('standards:')
for i,(x,y) in enumerate(zip(X,Y)): print(x,y)
import numpy as np
for deg in [1,2]:
    coeff=np.polyfit(X,Y,deg)
    pred=np.polyval(coeff,X)
    ss_res=np.sum((np.array(Y)-pred)**2); ss_tot=np.sum((np.array(Y)-np.mean(Y))**2)
    r2=1-ss_res/ss_tot
    print('deg',deg,'coeff',coeff,'r2',r2)
    for conc,well in [(90,'A3'),(90,'B3'),(90,'C3'),(90,'D3'),(300,'E3'),(300,'F3'),(300,'G3'),(300,'H3')]:
        y=data[well]
        # solve polyval = y roots
        roots=np.roots([*coeff[:-1], coeff[-1]-y]) if deg==2 else [(y-coeff[1])/coeff[0]]
        real=[r.real for r in roots if abs(r.imag)<1e-6]
        print(well,y,real)
PY"}

